record.field:
if inputs.get('ASF_001') and inputs['ASF_001'].amount > 0:
    result = inputs['ASF_001'].amount
else:
    result = 0.0
    tiene_derecho = False
    for pariente in employee.relative_ids:
        nombre_relacion = (pariente.relation_id.name or '').lower()
        if 'hij' not in nombre_relacion:
            continue
        limite_edad = pariente.max_age or 18
        if pariente.age < limite_edad or pariente.disability:
            tiene_derecho = True
            break
    if tiene_derecho:
        importe_mensual = payslip._rule_parameter('pe_asig_familiar')
        # ISM_001 = 1 en mensuales, semanas del mes en semanales
        semanas = result_rules['ISM_001']['total'] or 1.0
        result = importe_mensual / semanas
